INSERT INTO `faq` (`id`, `categoria`, `domanda`, `risposta1`, `risposta2`, `risposta3`, `data_aggiornamento`) VALUES
(1, 'generale', 'ciao', 'Ciao! Come posso aiutarti?', 'Salve! In cosa posso esserti utile?', 'Ciao! Hai bisogno di assistenza?', '2025-10-31 10:24:57'),
(3, 'generale', 'chi sei', 'Sono il Copilot Utixo, il tuo assistente digitale. Ti aiuto a trovare risposte rapide su domini, email, hosting e servizi cloud.', 'Sono il Copilot Utixo! Un assistente virtuale pensato per supportarti nelle attività tecniche e nei servizi Utixo.', 'Sono il chatbot di Utixo, progettato per darti supporto veloce su configurazioni, problemi tecnici e informazioni sui servizi.', '2025-12-05 10:45:23'),
(4, 'generale', 'cosa puoi fare', 'Posso aiutarti con domande su hosting, email, DNS, Microsoft 365 e molti altri servizi Utixo.', 'Ti supporto nella risoluzione di problemi tecnici, configurazioni e informazioni sui servizi Utixo.', 'Sono in grado di fornirti assistenza su email, dominio, hosting, pannelli di gestione e soluzioni cloud.', '2025-12-05 10:45:23'),
(5, 'generale', 'come funziona il supporto utixo', 'Il supporto Utixo è attivo tramite ticket, telefono e area clienti. I tecnici rispondono in base alla priorità e alla tipologia del servizio.', 'Puoi aprire un ticket dall’area clienti Utixo: un tecnico prenderà in carico la tua richiesta e ti aggiornerà fino alla risoluzione.', 'Il supporto avviene tramite ticket system: apri una richiesta e un tecnico Utixo ti risponderà il prima possibile.', '2025-12-05 10:45:23'),
(6, 'generale', 'come contatto assistenza', 'Puoi contattare l assistenza Utixo aprendo un ticket dall’area clienti.', 'Per ricevere supporto apri un ticket tramite la tua area riservata Utixo.', 'L assistenza tecnica risponde tramite ticket: accedi alla tua area clienti e apri una richiesta.', '2025-12-05 10:45:23'),
(7, 'generale', 'quali servizi offre utixo', 'Utixo offre hosting, email professionali, PEC, DNS, soluzioni cloud e Microsoft 365.', 'I servizi Utixo includono hosting condiviso, server cloud, email, PEC, backup, sicurezza e prodotti Microsoft.', 'Utixo fornisce servizi di hosting, posta elettronica, PEC, cloud, sicurezza IT e soluzioni Microsoft 365.', '2025-12-05 10:45:23'),
(8, 'generale', 'dove trovo area clienti', 'Puoi accedere all area clienti Utixo su https://shop.serverweb.net inserendo le tue credenziali.', 'L area clienti Utixo è disponibile sul portale ufficiale: https://shop.serverweb.net.', 'Accedi alla tua area riservata Utixo tramite https://shop.serverweb.net con username e password.', '2025-12-05 10:45:23'),
(9, 'generale', 'come recupero password area clienti', 'Clicca su Password Dimenticata nella pagina di login dell area clienti Utixo e inserisci la tua email.', 'Per recuperare la password dell area clienti premi su Recupera Password nella schermata di accesso.', 'Nella pagina di login dell area clienti trovi l’opzione Password Dimenticata per reimpostare la tua password.', '2025-12-05 10:45:23'),
(10, 'generale', 'non riesco ad accedere area clienti', 'Assicurati di usare l email con cui hai registrato il tuo account e prova a reimpostare la password.', 'Se non riesci ad accedere prova Recupero Password o verifica che l email sia quella corretta.', 'Puoi provare a reimpostare la password o aprire un ticket per assistenza all accesso.', '2025-12-05 10:45:23'),
(11, 'generale', 'dove trovo le fatture', 'Le fatture sono disponibili nell area clienti Utixo, sezione Fatture.', 'Puoi scaricare le tue fatture dall area clienti andando su Fatture > Documenti.', 'Le fatture Utixo sono visibili e scaricabili nella sezione dedicata dell area clienti.', '2025-12-05 10:45:23'),
(12, 'generale', 'come pago una fattura utixo', 'Puoi pagare le fatture tramite PayPal, carta, bonifico o direttamente dall area clienti.', 'Per pagare una fattura accedi all area clienti Utixo e clicca su Paga accanto alla fattura.', 'Le fatture Utixo possono essere saldate nell area clienti usando carta, PayPal o bonifico.', '2025-12-05 10:45:23'),
(13, 'certificati SSL', 'Cos\'è un certificato wildcard e come generare un CSR?', 'Un certificato SSL wildcard protegge tutti i sottodomini di un dominio principale. Il Common Name (CN) assume la forma *.dominio.est, dove l\'asterisco rappresenta qualsiasi sottodominio.', 'Un certificato SSL wildcard consente di proteggere tutti i sottodomini di un dominio principale. Il campo Common Name (CN) viene indicato come *.dominio.est, dove l’asterisco indica che qualsiasi sottodominio sarà coperto.', 'Il certificato SSL wildcard tutela tutti i sottodomini di un dominio principale. Nel Common Name (CN) si utilizza la forma *.dominio.est, con l’asterisco che rappresenta qualsiasi sottodominio.', '2026-01-23 09:20:49'),
(14, 'certificati SSL', 'A cosa serve un CSR?', 'un CSR (Certificate Signing Request) contiene:\r\n\r\nLa chiave pubblica associata al certificato e le informazioni identificative dell\'azienda a cui verrà rilasciato.\r\nIl CSR viene solitamente generato direttamente dal sistema che userà il certificato. Tuttavia, se il servizio non consente la creazione automatica del CSR, è possibile generarlo manualmente seguendo questa procedura.', 'Un CSR (Certificate Signing Request) include la chiave pubblica collegata al certificato e i dati identificativi dell’organizzazione destinataria. Di norma, il CSR viene creato direttamente dal sistema che utilizzerà il certificato; se ciò non fosse possibile, può essere generato manualmente seguendo una procedura specifica.', 'Il CSR (Certificate Signing Request) contiene la chiave pubblica del certificato e le informazioni relative all’azienda che ne farà uso. Solitamente viene generato automaticamente dal sistema interessato, ma qualora il servizio non lo supporti, è possibile produrlo manualmente seguendo i passaggi indicati.', '2026-01-23 09:28:45'),
(15, 'certificati SSL', 'cosa posso fare con cPanel?', 'Il pannello di controllo cPanel consente l’attivazione automatica di certificati SSL gratuiti tramite Let’s Encrypt o il sistema AutoSSL integrato. In molti casi, questi certificati possono essere utilizzati senza alcun costo aggiuntivo.', 'Il pannello di gestione cPanel permette di attivare automaticamente certificati SSL gratuiti attraverso Let’s Encrypt o il sistema AutoSSL integrato. Spesso, questi certificati possono essere utilizzati senza costi aggiuntivi.', 'Con cPanel è possibile abilitare automaticamente certificati SSL gratuiti tramite Let’s Encrypt o AutoSSL. In numerosi casi, l’uso di questi certificati non comporta alcuna spesa extra.', '2026-01-23 09:28:08'),
(16, 'certificati SSL', 'Cos\'è una richiesta di firma del certificato?', 'Una CSR è uno dei primi passaggi necessari per ottenere un certificato SSL/TLS.\r\n\r\nViene generata sul server dove il certificato verrà installato e include informazioni che l’Autorità di Certificazione (CA) utilizzerà per emettere il certificato. Contiene inoltre la chiave pubblica che sarà inclusa nel certificato, firmata con la chiave privata corrispondente.', 'La CSR rappresenta uno dei primi step per ottenere un certificato SSL/TLS. Viene creata sul server destinato all’installazione del certificato e racchiude le informazioni che l’Autorità di Certificazione (CA) utilizzerà per emetterlo. Include inoltre la chiave pubblica che sarà parte del certificato, firmata con la chiave privata corrispondente.', 'Generare una CSR è uno dei passaggi iniziali per richiedere un certificato SSL/TLS. La CSR viene prodotta sul server in cui il certificato sarà installato e contiene i dati che la CA userà per rilasciarlo, insieme alla chiave pubblica da includere nel certificato, firmata con la chiave privata associata.', '2026-01-23 09:30:35'),
(17, 'certificati SSL', 'Quali informazioni contiene una CSR?', 'Una CSR include dati essenziali relativi all’organizzazione e al dominio da certificare. Tra le informazioni principali:\r\n\r\nCommon Name (CN): nome di dominio completo (FQDN) del server.\r\nOrganizzazione (O): nome legale completo dell’azienda, senza abbreviazioni né suffissi come Inc., Srl, ecc.\r\nUnità organizzativa (OU): reparto aziendale che gestisce il certificato.\r\nCittà/Località (L): città dove si trova l’azienda (senza abbreviazioni).\r\nStato/Regione (S): stato o provincia dell’organizzazione (senza abbreviazioni).\r\nPaese (C): codice a due lettere del Paese in cui ha sede l’azienda.\r\nEmail: indirizzo e-mail di contatto.\r\nOltre ai dati anagrafici, la CSR include anche:\r\n\r\nChiave pubblica: utilizzata per crittografare le comunicazioni.\r\nTipo e lunghezza della chiave: la più comune è RSA 2048, ma sono supportate anche RSA 4096 o chiavi ECC.', 'Una CSR contiene le informazioni fondamentali relative all’organizzazione e al dominio da certificare. Tra i principali campi troviamo:\r\n\r\nCommon Name (CN): nome di dominio completo (FQDN) del server.\r\n\r\nOrganizzazione (O): nome legale completo dell’azienda, senza abbreviazioni né suffissi come Inc., Srl, ecc.\r\n\r\nUnità organizzativa (OU): reparto aziendale responsabile del certificato.\r\n\r\nCittà/Località (L): città in cui ha sede l’azienda (senza abbreviazioni).\r\n\r\nStato/Regione (S): stato o provincia dell’organizzazione (senza abbreviazioni).\r\n\r\nPaese (C): codice a due lettere del Paese di appartenenza.\r\n\r\nEmail: indirizzo e-mail di contatto.\r\n\r\nOltre ai dati identificativi, la CSR include anche:\r\n\r\nChiave pubblica: usata per crittografare le comunicazioni.\r\n\r\nTipo e lunghezza della chiave: la più comune è RSA 2048, ma possono essere utilizzate anche chiavi RSA 4096 o ECC.', 'La CSR raccoglie i dati essenziali dell’organizzazione e del dominio da certificare. Tra le informazioni principali:\r\n\r\nCN (Common Name): dominio completo del server (FQDN).\r\n\r\nO (Organizzazione): nome legale completo dell’azienda, senza abbreviazioni o suffissi.\r\n\r\nOU (Unità organizzativa): reparto incaricato della gestione del certificato.\r\n\r\nL (Città/Località): città dell’azienda (nessuna abbreviazione).\r\n\r\nS (Stato/Regione): stato o provincia dell’organizzazione.\r\n\r\nC (Paese): codice a due lettere del Paese di residenza.\r\n\r\nEmail: contatto e-mail.\r\n\r\nLa CSR comprende anche:\r\n\r\nChiave pubblica: per crittografare le comunicazioni.\r\n\r\nTipo e dimensione della chiave: tipicamente RSA 2048, ma sono supportate anche RSA 4096 o chiavi ECC.', '2026-01-23 09:32:01'),
(18, 'certificati SSL', 'Qual è il formato di una CSR?', 'La CSR è generalmente generata in formato PEM (Base-64) e può essere aperta con un semplice editor di testo. Deve sempre includere l’intestazione e il piè di pagina:\r\n\r\n-----BEGIN CERTIFICATE REQUEST-----\r\n[contenuto codificato base64]\r\n-----END CERTIFICATE REQUEST-----\r\nEsempio reale:\r\n\r\n-----BEGIN CERTIFICATE REQUEST-----\r\nMIICvDCCAaQCAQAwdzELMAkGA1UEBhMCVVMxDTALBgNVBAgMBFV0YWgxDzANBgNV...\r\n...Uo39lBi1w=\r\n-----END CERTIFICATE REQUEST-----', 'La CSR viene solitamente generata in formato PEM (Base-64) e può essere visualizzata con un normale editor di testo. Deve sempre contenere l’intestazione e il piè di pagina:\r\n\r\n-----BEGIN CERTIFICATE REQUEST-----\r\n[contenuto codificato base64]\r\n-----END CERTIFICATE REQUEST-----\r\n\r\n\r\nEsempio concreto:\r\n\r\n-----BEGIN CERTIFICATE REQUEST-----\r\nMIICvDCCAaQCAQAwdzELMAkGA1UEBhMCVVMxDTALBgNVBAgMBFV0YWgxDzANBgNV...\r\n...Uo39lBi1w=\r\n-----END CERTIFICATE REQUEST-----', 'La CSR è generalmente prodotta in formato PEM (Base-64) e può essere aperta con qualsiasi editor di testo. È essenziale includere sempre l’intestazione e il footer:\r\n\r\n-----BEGIN CERTIFICATE REQUEST-----\r\n[contenuto codificato base64]\r\n-----END CERTIFICATE REQUEST-----\r\n\r\n\r\nEsempio reale di CSR:\r\n\r\n-----BEGIN CERTIFICATE REQUEST-----\r\nMIICvDCCAaQCAQAwdzELMAkGA1UEBhMCVVMxDTALBgNVBAgMBFV0YWgxDzANBgNV...\r\n...Uo39lBi1w=\r\n-----END CERTIFICATE REQUEST-----', '2026-01-23 09:33:42'),
(19, 'certificati SSL', 'Come generare una CSR?\r\n', 'La procedura varia in base al sistema operativo o al pannello di controllo utilizzato. Abbiamo guide dettagliate per le principali piattaforme, tra cui:\r\n\r\ncPanel/WHM\r\nMicrosoft Exchange\r\nIIS (Internet Information Services)\r\nJava Keytool\r\nOpenSSL (Linux/Unix)\r\nConsulta la guida relativa al tuo ambiente per generare correttamente il file CSR.', 'La procedura cambia a seconda del sistema operativo o del pannello di controllo in uso. Disponiamo di guide dettagliate per le principali piattaforme, tra cui:\r\n\r\ncPanel/WHM\r\n\r\nMicrosoft Exchange\r\n\r\nIIS (Internet Information Services)\r\n\r\nJava Keytool\r\n\r\nOpenSSL (Linux/Unix)\r\n\r\nSegui la guida specifica per il tuo ambiente per generare correttamente il file CSR.', 'La modalità di generazione del CSR dipende dal sistema operativo o dal pannello di controllo adottato. Per le piattaforme più comuni sono disponibili guide complete, tra cui:\r\n\r\ncPanel/WHM\r\n\r\nMicrosoft Exchange\r\n\r\nIIS (Internet Information Services)\r\n\r\nJava Keytool\r\n\r\nOpenSSL (Linux/Unix)\r\n\r\nConsulta la guida corrispondente al tuo ambiente per creare correttamente il CSR.', '2026-01-23 09:35:28'),
(20, 'certificati SSL', 'Come generare una richiesta CSR per Apache2?', 'Se stai utilizzando un server Apache2 senza pannello di controllo grafico (es. cPanel), puoi generare una richiesta di firma del certificato (CSR) direttamente da linea di comando tramite SSH.\r\n\r\n \r\n\r\n1. Accedi al server via SSH\r\nUtilizza un client SSH (come PuTTY o il terminale) per connetterti al server dove verrà installato il certificato SSL.\r\n\r\n \r\n\r\n2. Comando per generare CSR e chiave privata\r\nEsegui il seguente comando:\r\n\r\nopenssl req -new -newkey rsa:2048 -nodes -keyout domain.key -out domain.csr\r\nSostituisci domain con il nome del tuo dominio (es. esempio.com). Il comando genererà due file:\r\n\r\ndomain.key → chiave privata\r\ndomain.csr → richiesta CSR\r\n \r\n\r\n3. Inserisci le informazioni richieste\r\nDopo aver eseguito il comando, ti verranno richiesti alcuni dati. Compila come segue:\r\n\r\nCommon Name (CN): il nome di dominio completo (es. www.esempio.com)\r\nWildcard: per certificati jolly, inserisci *.esempio.com\r\nOrganization (O): nome legale dell\'azienda\r\nOrganizational Unit (OU): reparto o nome commerciale (facoltativo)\r\nCity/Locality (L): città (senza abbreviazioni)\r\nState/Province (S): provincia o regione (senza abbreviazioni)\r\nCountry (C): codice ISO a due lettere (es. IT per Italia)\r\n \r\n\r\n4. Copia e incolla la CSR nel modulo di richiesta SSL\r\nApri il file domain.csr con un editor di testo (es. nano, vim o scaricalo via FTP) e copia l’intero contenuto, inclusi intestazione e piè di pagina:\r\n\r\n-----BEGIN CERTIFICATE REQUEST-----\r\n[contenuto codificato]\r\n-----END CERTIFICATE REQUEST-----\r\nIncolla questo contenuto nel modulo di richiesta SSL nel tuo account Utixo o presso il fornitore scelto.', 'Se utilizzi un server Apache2 senza pannello grafico (ad esempio cPanel), puoi generare una CSR direttamente da linea di comando tramite SSH.\r\n\r\n1. Accedi al server via SSH\r\nConnettiti al server usando un client SSH (come PuTTY o il terminale) sul server dove installerai il certificato SSL.\r\n\r\n2. Genera CSR e chiave privata\r\nEsegui il comando:\r\n\r\nopenssl req -new -newkey rsa:2048 -nodes -keyout domain.key -out domain.csr\r\n\r\n\r\nSostituisci domain con il tuo dominio (es. esempio.com). Questo creerà due file:\r\n\r\ndomain.key → chiave privata\r\n\r\ndomain.csr → richiesta CSR\r\n\r\n3. Inserisci le informazioni richieste\r\nQuando il comando ti chiederà dei dati, compila come segue:\r\n\r\nCommon Name (CN): nome di dominio completo (es. www.esempio.com\r\n)\r\n\r\nWildcard: per certificati jolly, inserisci *.esempio.com\r\n\r\nOrganization (O): nome legale dell’azienda\r\n\r\nOrganizational Unit (OU): reparto o nome commerciale (facoltativo)\r\n\r\nCity/Locality (L): città (senza abbreviazioni)\r\n\r\nState/Province (S): provincia o regione (senza abbreviazioni)\r\n\r\nCountry (C): codice ISO a due lettere (es. IT)\r\n\r\n4. Copia la CSR nel modulo di richiesta SSL\r\nApri il file domain.csr con un editor di testo (nano, vim o tramite FTP) e copia tutto il contenuto, inclusi intestazione e piè di pagina:\r\n\r\n-----BEGIN CERTIFICATE REQUEST-----\r\n[contenuto codificato]\r\n-----END CERTIFICATE REQUEST-----\r\n\r\n\r\nIncolla poi questo contenuto nel modulo di richiesta SSL del tuo account Utixo o presso il provider scelto.', 'Per server Apache2 senza pannello di controllo grafico, la CSR può essere generata via SSH direttamente da terminale.\r\n\r\n1. Connessione al server\r\nUsa un client SSH (ad esempio PuTTY o terminale) per accedere al server dove installerai il certificato SSL.\r\n\r\n2. Comando per generare CSR e chiave privata\r\n\r\nopenssl req -new -newkey rsa:2048 -nodes -keyout domain.key -out domain.csr\r\n\r\n\r\nSostituisci domain con il tuo dominio reale. Il comando produrrà:\r\n\r\ndomain.key → chiave privata\r\n\r\ndomain.csr → richiesta di certificato\r\n\r\n3. Compila i dati richiesti\r\nInserisci le informazioni richieste dal comando:\r\n\r\nCN (Common Name): dominio completo (es. www.esempio.com\r\n)\r\n\r\nWildcard: *.esempio.com per certificati jolly\r\n\r\nO (Organization): nome legale dell’azienda\r\n\r\nOU (Organizational Unit): reparto o nome commerciale (facoltativo)\r\n\r\nL (City/Locality): città (senza abbreviazioni)\r\n\r\nS (State/Province): provincia o regione (senza abbreviazioni)\r\n\r\nC (Country): codice ISO a due lettere (es. IT)\r\n\r\n4. Inserisci la CSR nel modulo SSL\r\nApri domain.csr con un editor di testo o scaricalo via FTP e copia l’intero contenuto, intestazione e piè di pagina inclusi:\r\n\r\n-----BEGIN CERTIFICATE REQUEST-----\r\n[contenuto codificato]\r\n-----END CERTIFICATE REQUEST-----\r\n\r\n\r\nIncolla il contenuto nel modulo di richiesta SSL del tuo provider o del tuo account Utixo.', '2026-01-23 09:37:24'),
(21, 'certificati SSL', 'Come posso installareun certificato SSL su GlassFish?', 'Apri la console dei comandi (cmd) e accedi alla cartella config del dominio GlassFish. Esempio:\r\n\r\ncd glassfish4\\glassfish\\domains\\domain1\\config\r\n \r\n\r\n1. Creazione della chiave (solo per prima installazione)\r\nSe non è già presente una chiave nel keystore, esegui il seguente comando per crearla:\r\n\r\nkeytool -genkey -alias nomeAlias -keyalg RSA -keysize 2048 -keystore keystore.jks -noprompt -v -dname \"CN=dominio,O=società,OU=proprietario,L=città,S=nazione,C=siglaNazione\" -storepass changeit\r\nSostituisci nomeAlias con un identificativo del dominio, ad esempio senza punti (esempiocom).\r\n\r\n \r\n\r\n2. Generazione della CSR\r\nPer richiedere un certificato, genera la CSR con il comando:\r\n\r\nkeytool -certreq -alias nomeAlias -file nomeAlias.csr -keystore keystore.jks -storepass changeit\r\nCarica la CSR nel control panel Utixo e scegli un metodo di validazione (email o DNS).\r\n\r\n \r\n\r\n3a. Importazione certificati (formato CRT separato)\r\nSe hai ricevuto i certificati in formato singolo (root, intermediate, dominio):\r\n\r\nPulisci i certificati precedenti\r\nkeytool -delete -alias root -keystore keystore.jks -storepass changeit\r\nkeytool -delete -alias intermed -keystore keystore.jks -storepass changeit\r\nkeytool -delete -alias root -keystore cacerts.jks -storepass changeit\r\nkeytool -delete -alias intermed -keystore cacerts.jks -storepass changeit\r\nImporta root, intermedi e certificato dominio\r\nkeytool -import -trustcacerts -alias root -file AAACertificateServices.crt -keystore keystore.jks -storepass changeit\r\nkeytool -import -trustcacerts -alias intermed -file USERTrustRSAAAACA.crt -keystore keystore.jks -storepass changeit\r\nkeytool -import -trustcacerts -alias SectigoRSADomainValidationSecureServerCA -file SectigoRSADomainValidationSecureServerCA.crt -keystore keystore.jks -storepass changeit\r\nkeytool -import -trustcacerts -alias nomeAlias -file nomeAlias.crt -keystore keystore.jks -storepass changeit\r\n\r\nkeytool -import -trustcacerts -alias root -file AAACertificateServices.crt -keystore cacerts.jks -storepass changeit\r\nkeytool -import -trustcacerts -alias intermed -file USERTrustRSAAAACA.crt -keystore cacerts.jks -storepass changeit\r\nkeytool -import -trustcacerts -alias SectigoRSADomainValidationSecureServerCA -file SectigoRSADomainValidationSecureServerCA.crt -keystore cacerts.jks -storepass changeit\r\n \r\n\r\n3b. Importazione certificati (CA Bundle o P7B)\r\nSe hai ricevuto un file .ca-bundle o .p7b, procedi così:\r\n\r\nPulisci i certificati precedenti\r\nkeytool -delete -alias cabundle -keystore keystore.jks -storepass changeit\r\nkeytool -delete -alias cabundle -keystore cacerts.jks -storepass changeit\r\nImporta bundle e certificato dominio\r\nkeytool -import -trustcacerts -alias cabundle -file nomeAlias.ca-bundle -keystore keystore.jks -storepass changeit\r\nkeytool -import -trustcacerts -alias nomeAlias -file nomeAlias.crt -keystore keystore.jks -storepass changeit\r\noppure:\r\n\r\nkeytool -import -trustcacerts -alias nomeAlias -file nomeAlias.p7b -keystore keystore.jks -storepass changeit\r\nkeytool -import -trustcacerts -alias cabundle -file nomeAlias.ca-bundle -keystore cacerts.jks -storepass changeit\r\n \r\n\r\n4. Verifica dell\'importazione\r\nkeytool -list -alias nomeAlias -keystore keystore.jks -storepass changeit\r\n \r\n\r\n5. Associare il certificato in GlassFish\r\nAccedi alla console GlassFish e vai su:\r\n\r\nConfigurazioni → server-config → Servizio HTTP → Listener HTTP → http-listener-2 → SSL\r\n\r\nInserisci nomeAlias nella casella Alias certificato per attivarlo.\r\n\r\n \r\n\r\n6. Riavviare GlassFish\r\nRiavvia il server GlassFish per applicare le modifiche e rendere attivo il nuovo certificato SSL.', 'Apri il prompt dei comandi (cmd) e posizionati nella cartella config del dominio GlassFish, ad esempio:\r\n\r\ncd glassfish4\\glassfish\\domains\\domain1\\config\r\n\r\n\r\n1. Creazione della chiave (solo al primo setup)\r\nSe non è presente una chiave nel keystore, esegui:\r\n\r\nkeytool -genkey -alias nomeAlias -keyalg RSA -keysize 2048 -keystore keystore.jks -noprompt -v -dname \"CN=dominio,O=società,OU=proprietario,L=città,S=nazione,C=siglaNazione\" -storepass changeit\r\n\r\n\r\nSostituisci nomeAlias con un identificativo del dominio, senza punti (es. esempiocom).\r\n\r\n2. Generazione della CSR\r\nPer richiedere il certificato, crea la CSR:\r\n\r\nkeytool -certreq -alias nomeAlias -file nomeAlias.csr -keystore keystore.jks -storepass changeit\r\n\r\n\r\nCarica il file .csr nel control panel Utixo e scegli il metodo di validazione (email o DNS).\r\n\r\n3a. Importazione certificati separati (CRT)\r\nSe hai ricevuto certificati separati (root, intermedi, dominio):\r\n\r\nElimina certificati precedenti\r\n\r\nkeytool -delete -alias root -keystore keystore.jks -storepass changeit\r\nkeytool -delete -alias intermed -keystore keystore.jks -storepass changeit\r\nkeytool -delete -alias root -keystore cacerts.jks -storepass changeit\r\nkeytool -delete -alias intermed -keystore cacerts.jks -storepass changeit\r\n\r\n\r\nImporta root, intermedi e certificato dominio\r\n\r\nkeytool -import -trustcacerts -alias root -file AAACertificateServices.crt -keystore keystore.jks -storepass changeit\r\nkeytool -import -trustcacerts -alias intermed -file USERTrustRSAAAACA.crt -keystore keystore.jks -storepass changeit\r\nkeytool -import -trustcacerts -alias SectigoRSADomainValidationSecureServerCA -file SectigoRSADomainValidationSecureServerCA.crt -keystore keystore.jks -storepass changeit\r\nkeytool -import -trustcacerts -alias nomeAlias -file nomeAlias.crt -keystore keystore.jks -storepass changeit\r\nkeytool -import -trustcacerts -alias root -file AAACertificateServices.crt -keystore cacerts.jks -storepass changeit\r\nkeytool -import -trustcacerts -alias intermed -file USERTrustRSAAAACA.crt -keystore cacerts.jks -storepass changeit\r\nkeytool -import -trustcacerts -alias SectigoRSADomainValidationSecureServerCA -file SectigoRSADomainValidationSecureServerCA.crt -keystore cacerts.jks -storepass changeit\r\n\r\n\r\n3b. Importazione certificati in bundle (.ca-bundle o .p7b)\r\n\r\nElimina bundle precedenti\r\n\r\nkeytool -delete -alias cabundle -keystore keystore.jks -storepass changeit\r\nkeytool -delete -alias cabundle -keystore cacerts.jks -storepass changeit\r\n\r\n\r\nImporta bundle e certificato dominio\r\n\r\nkeytool -import -trustcacerts -alias cabundle -file nomeAlias.ca-bundle -keystore keystore.jks -storepass changeit\r\nkeytool -import -trustcacerts -alias nomeAlias -file nomeAlias.crt -keystore keystore.jks -storepass changeit\r\n\r\n\r\noppure:\r\n\r\nkeytool -import -trustcacerts -alias nomeAlias -file nomeAlias.p7b -keystore keystore.jks -storepass changeit\r\nkeytool -import -trustcacerts -alias cabundle -file nomeAlias.ca-bundle -keystore cacerts.jks -storepass changeit\r\n\r\n\r\n4. Verifica dell’importazione\r\n\r\nkeytool -list -alias nomeAlias -keystore keystore.jks -storepass changeit\r\n\r\n\r\n5. Associare il certificato in GlassFish\r\nAccedi alla console GlassFish:\r\n\r\nConfigurazioni → server-config → Servizio HTTP → Listener HTTP → http-listener-2 → SSL\r\n\r\n\r\nInserisci nomeAlias nella casella “Alias certificato” per attivarlo.\r\n\r\n6. Riavvia GlassFish\r\nRiavvia il server per applicare le modifiche e rendere operativo il nuovo certificato SSL.', 'Apri cmd e vai nella cartella config\r\n\r\ncd glassfish4\\glassfish\\domains\\domain1\\config\r\n\r\n\r\nCrea chiave (solo al primo setup)\r\n\r\nkeytool -genkey -alias nomeAlias -keyalg RSA -keysize 2048 -keystore keystore.jks -noprompt -v -dname \"CN=dominio,O=società,OU=proprietario,L=città,S=nazione,C=siglaNazione\" -storepass changeit\r\n\r\n\r\nGenera CSR\r\n\r\nkeytool -certreq -alias nomeAlias -file nomeAlias.csr -keystore keystore.jks -storepass changeit\r\n\r\n\r\nCarica il .csr su Utixo e seleziona il metodo di validazione.\r\n\r\nImporta certificati\r\n\r\nSe CRT separati: elimina vecchi certificati e importa root, intermedi e dominio.\r\n\r\nSe CA bundle (.ca-bundle o .p7b): elimina vecchi bundle e importa nuovo bundle e certificato dominio.\r\n\r\nVerifica importazione\r\n\r\nkeytool -list -alias nomeAlias -keystore keystore.jks -storepass changeit\r\n\r\n\r\nAssociare certificato in GlassFish\r\nConsole → Configurazioni → server-config → Servizio HTTP → Listener HTTP → http-listener-2 → SSL → inserisci alias.\r\n\r\nRiavvia GlassFish\r\nPer rendere attivo il certificato SSL.', '2026-01-23 09:40:23'),
(22, 'certificati SSL', 'Che cos\'è il controllo CAA?', 'Il controllo CAA (Certificate Authority Authorization) è un meccanismo di sicurezza basato su DNS che consente ai proprietari di un dominio di specificare quali Autorità di Certificazione (CA) sono autorizzate a emettere certificati SSL/TLS per quel dominio.\r\n\r\nConfigurando un record CAA all’interno del DNS del proprio dominio, è possibile limitare l’emissione dei certificati solo ad alcune CA specifiche. Questo riduce il rischio che una CA non autorizzata rilasci un certificato fraudolento o non conforme.\r\n\r\nAd esempio, se si desidera autorizzare solo sectigo.com come CA, si può configurare un record come il seguente:\r\n\r\nexample.com.  CAA  0 issue \"sectigo.com\"\r\n\r\nUn CAA:\r\nAumenta la sicurezza del dominio contro emissioni non autorizzate\r\nÈ supportato da tutte le CA principali e considerato uno standard di buona pratica\r\nÈ raccomandato per i domini pubblici che richiedono certificati SSL/TLS\r\n\r\nQuando una CA riceve una richiesta per emettere un certificato SSL/TLS, esegue una query DNS sul record CAA del dominio. Se non trova il proprio nome all’interno del record, rifiuterà la richiesta di certificato.', 'Il controllo CAA (Certificate Authority Authorization) è un meccanismo di sicurezza basato su DNS che permette ai proprietari di un dominio di indicare quali Autorità di Certificazione (CA) sono autorizzate a emettere certificati SSL/TLS per quel dominio.\r\n\r\nConfigurando un record CAA nel DNS del proprio dominio, si limita l’emissione dei certificati solo alle CA specificate, riducendo il rischio di certificati emessi da CA non autorizzate o fraudolente.\r\n\r\nAd esempio, per autorizzare solo sectigo.com come CA:\r\n\r\nexample.com.  CAA  0 issue \"sectigo.com\"\r\n\r\n\r\nVantaggi del CAA:\r\n\r\nAumenta la sicurezza del dominio contro emissioni non autorizzate\r\n\r\nSupportato da tutte le principali CA ed è considerato una best practice\r\n\r\nRaccomandato per domini pubblici che richiedono certificati SSL/TLS\r\n\r\nQuando una CA riceve una richiesta di certificato, verifica il record CAA del dominio tramite DNS. Se il proprio nome non è presente, la richiesta viene rifiutata.', 'Il CAA (Certificate Authority Authorization) è un record DNS che consente ai proprietari di dominio di specificare quali CA possono emettere certificati SSL/TLS per il loro dominio.\r\n\r\nConfigurando correttamente il CAA, si impedisce a CA non autorizzate di rilasciare certificati, aumentando la sicurezza.\r\n\r\nEsempio per autorizzare solo sectigo.com:\r\n\r\nexample.com.  CAA  0 issue \"sectigo.com\"\r\n\r\n\r\nPunti chiave:\r\n\r\nProtegge il dominio da emissioni di certificati non autorizzate\r\n\r\nSupportato da tutte le principali CA\r\n\r\nRaccomandato per domini pubblici che richiedono SSL/TLS\r\n\r\nQuando una CA riceve una richiesta di certificato, controlla il record CAA tramite DNS e rifiuta la richiesta se il suo nome non è autorizzato.', '2026-01-23 09:43:19'),
(25, 'CloudFlare', 'come attivo la modalità i\'m under attack su cloudflare?', 'Accedi al portale shop.serverweb.net con le tue credenziali, cerca “Cloud” nei servizi e apri il prodotto Cloudflare Security Services. Scorri e clicca su “Manage Cloudflare”, poi vai in Firewall e nel campo “Security Level” seleziona “I\'m Under Attack”.', 'Per attivare “I\'m Under Attack”: portale Utixo → Services → Cloudflare Security Services → “Manage Cloudflare” → sezione Firewall → “Security Level” → “I\'m Under Attack”.', 'La modalità “I\'m Under Attack” si abilita dal pannello di gestione Cloudflare: entra in “Manage Cloudflare”, apri Firewall e imposta il livello di sicurezza su “I\'m Under Attack”.', '2026-02-20 09:00:00'),
(26, 'CloudFlare', 'come gestisco i dns cloudflare dal pannello utixo ucmp?', 'Dal portale Utixo vai su Home → Services, individua il servizio del dominio e clicca “Manage”. Nella pagina di gestione premi “MANAGE CLOUDFLARE”, poi apri la tile “DNS”: qui puoi aggiungere o modificare record (A, CNAME, MX, TXT, ecc.).', 'Percorso rapido: UCMP/Portale Utixo → Services → Manage sul servizio dominio → “MANAGE CLOUDFLARE” → “DNS”. Da lì aggiungi/modifichi i record DNS.', 'Per gestire i DNS Cloudflare dal pannello Utixo: entra nel servizio, apri “MANAGE CLOUDFLARE” e poi “DNS”. Inserisci i dati del record e conferma con “ADD NEW DNS RECORD/Continue”.', '2026-02-20 09:00:00'),
(27, 'CloudFlare', 'dove trovo manage cloudflare per gestire sicurezza e performance?', 'Dopo aver selezionato il servizio Cloudflare dal portale Utixo, clicca su “Manage Cloudflare” per aprire la console. Da lì gestisci DNS, caching, livello di protezione e firewall.', 'Per accedere alla console centralizzata: seleziona il servizio Cloudflare e premi “Manage Cloudflare”. Troverai le sezioni principali (DNS, Caching, Protection level, Firewall).', 'Il pulsante “Manage Cloudflare” ti porta al pannello di gestione da cui controlli le funzioni principali di Cloudflare (DNS, cache e sicurezza).', '2026-02-20 09:00:00'),
(28, 'CloudFlare', 'come blocco un paese specifico su cloudflare?', 'Nel Cloudflare Dashboard seleziona il dominio, poi vai su Security → WAF → Firewall Rules. Crea una nuova regola, imposta come condizione il paese e scegli l’azione (Allow/Block/Challenge/JS Challenge). Infine clicca “Deploy”.', 'Per bloccare un paese: Cloudflare → dominio → Security > WAF > Firewall Rules → “Create a Firewall Rule” → scegli il paese → azione “Block” (o Challenge) → “Deploy”.', 'Con le Firewall Rules puoi filtrare per nazione: crea una regola sul paese e applica l’azione desiderata (blocca, consenti o verifica con challenge).', '2026-02-20 09:00:00'),
(29, 'CloudFlare', 'quali funzionalità cloudflare sono disponibili dal pannello utixo?', 'Dal pannello Utixo puoi accedere rapidamente alle principali funzioni Cloudflare: DNS (anche DNSSEC), Crypto/SSL (Flexible/Full/Full Strict), e Firewall (regole, WAF, blocchi per IP/paese/ASN e bot management).', 'Le funzioni principali disponibili includono: DNS ad alte prestazioni con propagazione rapida, SSL/TLS (più modalità e HTTPS rewrites) e strumenti di firewall/WAF per protezione da attacchi e traffico malevolo.', 'Cloudflare tramite Utixo offre un set completo per sicurezza e gestione: DNS, cifratura SSL/TLS e firewall avanzato con WAF e regole personalizzabili.', '2026-02-20 09:00:00'),
(30, 'CloudFlare', 'cos\'è il waf di cloudflare e cosa protegge?', 'Il WAF (Web Application Firewall) di Cloudflare protegge il sito da vulnerabilità comuni come SQL injection, XSS e altre minacce note o zero-day. È aggiornato costantemente e lavora in tempo reale.', 'Il WAF di Cloudflare è un firewall applicativo che blocca attacchi web (es. SQL injection e cross-site scripting). Le regole vengono aggiornate per adattarsi a nuove minacce.', 'Con Cloudflare WAF ottieni protezione attiva contro attacchi applicativi: filtra richieste malevole e riduce i rischi legati a vulnerabilità del sito.', '2026-02-20 09:00:00'),
(31, 'CloudFlare', 'cos\'è l\'ssl offloading di cloudflare e quali porte supporta?', 'Con lo SSL offloading Cloudflare gestisce la cifratura HTTPS sul proprio edge e può fare da proxy tra visitatore e server. Le porte HTTPS supportate per il proxy/SSL sono: 443, 2053, 2083, 2087, 2096, 8443.', 'Lo SSL offloading permette a Cloudflare di terminare SSL/TLS e proteggere la navigazione; per usarlo con traffico HTTPS proxato sono supportate solo alcune porte (443, 2053, 2083, 2087, 2096, 8443).', 'Se usi Cloudflare come proxy HTTPS, verifica che il servizio stia ascoltando su una porta supportata: 443 o una tra 2053/2083/2087/2096/8443.', '2026-02-20 09:00:00'),
(32, 'Cloud Backup', 'come accedo alla console acronis per il cloud backup?', 'Per accedere direttamente alla console Acronis, visita cloud.acronis.com e fai login usando il tuo user ID e la tua password.', 'Accesso console Acronis: apri cloud.acronis.com e accedi con user ID e password.', 'La console di gestione Cloud Backup (Acronis) è raggiungibile da cloud.acronis.com: effettua l’accesso con le credenziali (user ID e password).', '2026-02-20 09:00:00'),
(33, 'Cloud Backup', 'qual è il link per entrare nel pannello acronis del cloud backup?', 'Il link diretto per la console Acronis è cloud.acronis.com. Accedi con user ID e password.', 'Per entrare nel pannello Acronis: vai su cloud.acronis.com e fai login con le tue credenziali.', 'La console Acronis per il Cloud Backup si apre da cloud.acronis.com, con accesso tramite user ID e password.', '2026-02-20 09:00:00'),
(34, 'Cloud Backup', 'che credenziali servono per entrare in acronis cloud?', 'Per entrare nella console Acronis (cloud.acronis.com) devi autenticarti con il tuo user ID e la tua password.', 'Login Acronis: user ID + password, direttamente su cloud.acronis.com.', 'L’accesso alla console Acronis richiede user ID e password (da usare su cloud.acronis.com).', '2026-02-20 09:00:00'),
(35, 'Cloud Backup', 'posso accedere ad acronis senza passare dal portale?', 'Sì: la KB indica l’accesso diretto alla console Acronis da cloud.acronis.com, effettuando il login con user ID e password.', 'Accesso diretto disponibile: apri cloud.acronis.com e accedi con user ID e password.', 'Puoi entrare direttamente nella console Acronis dal sito cloud.acronis.com, usando user ID e password.', '2026-02-20 09:00:00'),
(36, 'Email archiving', 'come accedo al sistema di email archiving?', 'Per accedere al sistema di email archiving, utilizza l’indirizzo https://mailarchive.utixo.net:8462 ed effettua il login con le credenziali (nome utente e password) fornite durante l’attivazione del prodotto.', 'Accesso rapido: apri https://mailarchive.utixo.net:8462 e fai login con username e password ricevute in fase di attivazione.', 'Il pannello di email archiving è raggiungibile da https://mailarchive.utixo.net:8462: accedi con le credenziali fornite al momento dell’attivazione.', '2026-02-20 09:00:00'),
(37, 'Email archiving', 'qual è il link per entrare nella piattaforma di archiviazione email?', 'Il link diretto alla piattaforma di email archiving è https://mailarchive.utixo.net:8462.', 'Per entrare nel sistema di archiviazione email: vai su https://mailarchive.utixo.net:8462 e accedi con le tue credenziali.', 'La piattaforma di archiviazione email è disponibile all’indirizzo https://mailarchive.utixo.net:8462 (accesso con username e password).', '2026-02-20 09:00:00'),
(38, 'Email archiving', 'che credenziali servono per il login al sistema di email archiving?', 'Per il login servono nome utente e password forniti durante l’attivazione del prodotto. L’accesso avviene da https://mailarchive.utixo.net:8462.', 'Le credenziali di accesso (username e password) vengono rilasciate in fase di attivazione e si usano su https://mailarchive.utixo.net:8462.', 'Per entrare nel sistema di email archiving devi usare le credenziali ricevute all’attivazione (nome utente e password).', '2026-02-20 09:00:00'),
(39, 'Email archiving', 'quali server di posta sono supportati per l\'archiviazione email?', 'Sono supportati Microsoft Exchange Server (2003/2007/2010/2013/2016/2019), Microsoft 365, Google Workspace (ex G Suite) e, in generale, tutti i server compatibili con IMAP o POP3.', 'Compatibilità: Exchange (2003–2019), Microsoft 365, Google Workspace e qualsiasi server IMAP/POP3.', 'Il sistema di email archiving supporta i principali ambienti (Exchange, Microsoft 365, Google Workspace) e tutti i server che espongono IMAP o POP3.', '2026-02-20 09:00:00'),
(40, 'Email archiving', 'il sistema di email archiving supporta imap o pop3?', 'Sì: il sistema è compatibile con tutti i server di posta che supportano i protocolli IMAP o POP3.', 'Se il tuo server espone IMAP o POP3, puoi archiviarne le email tramite il sistema di email archiving.', 'La compatibilità include qualsiasi server email IMAP/POP3 (oltre a Exchange/M365/Workspace).', '2026-02-20 09:00:00'),
(41, 'Email archiving', 'posso archiviare email da mdaemon icewarp o kerio connect?', 'Sì: tra i sistemi supportati sono inclusi MDaemon, IceWarp e Kerio Connect (oltre a Exchange, Microsoft 365, Google Workspace e server IMAP/POP3).', 'MDaemon, IceWarp e Kerio Connect sono indicati come sistemi compatibili per l’archiviazione email.', 'È possibile archiviare email provenienti anche da MDaemon, IceWarp e Kerio Connect.', '2026-02-20 09:00:00'),
(42, 'Email archiving', 'posso importare file pst o eml nel sistema di email archiving?', 'Sì: è possibile archiviare anche da file email, inclusi i formati .PST, .EML e altri formati standard.', 'Import supportato: file di posta come .PST e .EML (oltre ad altri formati standard).', 'Il sistema supporta l’archiviazione anche tramite file email (es. PST/EML).', '2026-02-20 09:00:00'),
(43, 'Email archiving', 'posso archiviare email partendo da client come outlook o thunderbird?', 'Sì: tra le sorgenti supportate rientrano anche client di posta come Microsoft Outlook e Mozilla Thunderbird.', 'È possibile archiviare email anche tramite client come Outlook e Thunderbird.', 'Outlook e Thunderbird sono indicati tra i client compatibili per l’archiviazione manuale o da file.', '2026-02-20 09:00:00'),
(44, 'email security web - libraesva', 'come accedo alla console libraesva per gestire quarantena whitelist e blacklist?', 'Accedi alla console Libraesva da https://spam.utixo.net. Inserisci il tuo indirizzo email e, se è il primo accesso, usa “Forgot your Password?” per impostare la password.', 'Percorso rapido: https://spam.utixo.net → inserisci email → “Forgot your Password?” → segui la mail di recupero.', 'La gestione di quarantena/whitelist/blacklist avviene dalla console Libraesva raggiungibile su https://spam.utixo.net con accesso tramite email e password (prima impostazione via “Forgot your Password?”).', '2026-02-20 09:00:00'),
(45, 'email security web - libraesva', 'non ho la password libraesva come la recupero?', 'Vai su https://spam.utixo.net, inserisci il tuo indirizzo email e clicca su “Forgot your Password?”. Riceverai un’email di recupero password.', 'Recupero password: https://spam.utixo.net → email → “Forgot your Password?” → apri la mail di reset.', 'Se non ricordi la password, usa la procedura “Forgot your Password?” sulla console https://spam.utixo.net: ti arriva una mail per reimpostarla.', '2026-02-20 09:00:00'),
(46, 'email security web - libraesva', 'nella mail di recupero libraesva cosa devo cliccare per entrare?', 'Nell’email di recupero/attivazione, clicca su “Authenticate this device” per autenticare il dispositivo e completare l’accesso al sistema.', 'Dopo il reset password, apri la mail e premi “Authenticate this device” per accedere alla console.', 'Per completare l’accesso dopo il recupero, va cliccato “Authenticate this device” dentro l’email ricevuta.', '2026-02-20 09:00:00'),
(47, 'email security web - libraesva', 'come sblocco una mail finita in quarantena su libraesva?', 'Dalla console Libraesva apri la quarantena: clicca sull’icona con le due frecce gialle per rilasciare (release) l’email e inoltrarla al destinatario.', 'Quarantena → seleziona il messaggio → icona con due frecce gialle (release) per consegnare la mail.', 'Per sbloccare una mail in quarantena, usa l’azione di rilascio (icone “due frecce gialle”): la mail viene inoltrata al destinatario.', '2026-02-20 09:00:00'),
(48, 'email security web - libraesva', 'come vedo perché una mail è stata bloccata e che spam score ha?', 'Nella lista, clicca sull’icona con la busta a sinistra: puoi vedere la causa del blocco e lo SPAM score assegnato al messaggio.', 'Per dettaglio blocco e punteggio: icona busta (a sinistra) sul messaggio.', 'Il motivo del blocco e lo spam score si consultano aprendo i dettagli del messaggio (icona busta a sinistra).', '2026-02-20 09:00:00'),
(49, 'email security web - libraesva', 'se rilascio una mail dalla quarantena viene ancora considerata spam?', 'No: le email rilasciate dalla quarantena vengono considerate come mail “Clean” (normali) e non classificate come SPAM.', 'Dopo il release, la mail viene trattata come “Clean email”.', 'Una mail rilasciata dalla quarantena viene inoltrata e non viene più classificata come spam, ma come “Clean”.', '2026-02-20 09:00:00'),
(50, 'email security web - libraesva', 'quali record mx devo impostare per usare email security suite libraesva?', 'Dopo l’attivazione del servizio, imposta gli MX nel DNS per instradare il traffico su Utixo: 10 mx1.utixo.net e 10 mx2.utixo.net (in alcune configurazioni è presente anche 20 mx1.acsitalia.net).', 'Configurazione MX (priorità): 10 mx1.utixo.net; 10 mx2.utixo.net; (eventuale) 20 mx1.acsitalia.net.', 'Gli MX vanno puntati ai server Utixo (mx1.utixo.net e mx2.utixo.net) con le priorità indicate, così l’SMTP passa dal filtro di protezione.', '2026-02-20 09:00:00'),
(51, 'email security web - libraesva', 'ricevo spam ma non lo vedo passare dalla console libraesva come mai?', 'Probabile bypass: gli spammer possono inviare direttamente all’IP del mail server saltando il filtro. Per evitare, configura il server per accettare email in ingresso solo dai server Utixo: mx1.utixo.net (46.105.87.130) e mx2.utixo.net (5.9.150.87).', 'Soluzione: blocca le consegne dirette e consenti solo le IP dei relay Utixo (46.105.87.130 e 5.9.150.87) come sorgenti autorizzate.', 'Se il server accetta posta “diretta”, è un rischio: limita l’ingresso alle sole IP dei MX Utixo (mx1/mx2) così tutto passa dalla protezione Libraesva.', '2026-02-20 09:00:00'),
(52, 'email security web - libraesva', 'come genero e attivo la dkim su libraesva esg?', 'Accedi al pannello https://spam.utixo.net e vai in System → Mail Transport → DKIM Signing. Aggiungi il dominio e genera la chiave DKIM; poi pubblica nel DNS il record DKIM indicato dal pannello.', 'Percorso: spam.utixo.net → System → Mail Transport → DKIM Signing → Aggiungi dominio → genera DKIM → copia i record DNS.', 'Per configurare DKIM: entra nella sezione DKIM Signing del pannello Libraesva, aggiungi il dominio e pubblica in DNS la chiave/record fornito.', '2026-02-20 09:00:00'),
(53, 'email security web - libraesva', 'cos è urlsand e perché i link nelle email diventano “protetti”?', 'UrlSand è una protezione avanzata che scansiona i link nelle email e blocca URL malevoli (es. spear-phishing, exploit zero-day, ransomware). La protezione avviene “al click”, non solo alla ricezione.', 'I link “riscritti” servono a farli passare da UrlSand: vengono controllati quando li apri, su qualsiasi dispositivo.', 'UrlSand protegge i collegamenti email: i link vengono verificati e filtrati al momento dell’apertura per impedire URL pericolosi.', '2026-02-20 09:00:00'),
(54, 'email security web - libraesva', 'che cos è quicksand e perché vedo l allegato utixo-attachment-warning.txt?', 'QuickSand Sandbox rimuove contenuti attivi pericolosi da PDF e documenti Office (es. JavaScript nei PDF, macro o script nei documenti). Per questo può comparire un file aggiuntivo tipo “Utixo-Attachment-Warning.txt” che segnala l’operazione.', 'Se vedi “Utixo-Attachment-Warning.txt”, è un avviso: QuickSand ha “disarmato” l’allegato eliminando parti attive potenzialmente dannose.', 'Il file warning compare quando QuickSand sanitizza allegati Office/PDF: segnala che contenuti attivi (macro/script/JS) sono stati rimossi per sicurezza.', '2026-02-20 09:00:00'),
(55, 'email security web - libraesva', 'cos è il whaling e come mi posso difendere?', 'Il whaling è una variante di phishing basata su social engineering che prende di mira dirigenti e top management per indurli a compiere azioni dannose (es. pagamenti, condivisione credenziali).', 'Difesa pratica: verifica sempre richieste “urgenti” (pagamenti/cambi IBAN) con un secondo canale (telefonata), controlla attentamente mittente e dominio.', 'Il whaling colpisce i vertici aziendali: per ridurre il rischio, conferma operazioni sensibili con procedure interne e controlli sul mittente.', '2026-02-20 09:00:00'),
(56, 'email security web - libraesva', 'come modifico una regola già creata in whitelist o blacklist su libraesva?', 'Dopo aver creato una regola in White & Black list, puoi modificarla cliccando sull’icona **matita gialla** nella riga della regola.', 'White & Black list → trova la regola → icona **matita gialla** per editare.', 'Le regole whitelist/blacklist sono modificabili dalla tabella usando l’icona **pencil** (matita gialla).', '2026-02-20 09:00:00'),
(57, 'email security web - libraesva', 'come elimino una singola regola di whitelist o blacklist su libraesva?', 'Nella sezione White & Black list puoi eliminare una regola usando l’icona **cestino rosso** nella riga della regola.', 'White & Black list → regola → **cestino rosso** per cancellare.', 'Per cancellare una whitelist/blacklist già creata, usa l’icona di eliminazione (cestino rosso) dalla tabella.', '2026-02-20 09:00:00'),
(58, 'email security web - libraesva', 'come cancello più regole whitelist blacklist insieme su libraesva?', 'Se devi eliminare più regole, selezionale mettendo la spunta nella casella a sinistra di ogni riga e poi clicca **Delete Selected** (icona cestino rosso in alto).', 'Spunta più righe → **Delete Selected** (cestino rosso) per eliminazione massiva.', 'Per cancellazioni multiple: seleziona le regole dalla colonna checkbox e usa **Delete Selected** in alto nella tabella.', '2026-02-20 09:00:00'),
(59, 'email security web - libraesva', 'nel quarantine report cosa significa release?', 'Nel Quarantine Report l’azione **Release** consegna subito il messaggio selezionato nella tua inbox.', 'Quarantine Report → Release = consegna immediata in posta in arrivo.', '“Release” nel report di quarantena vuol dire: rilascia e recapita subito l’email.', '2026-02-20 09:00:00'),
(60, 'email security web - libraesva', 'a cosa serve il quarantine report e cosa contiene?', 'Il Quarantine Report è una mail automatica di riepilogo che elenca i messaggi bloccati dal filtro antispam e ti permette di gestirli direttamente dal report.', 'È un riepilogo periodico dei messaggi in quarantena con azioni rapide (es. release/whitelist).', 'Serve per avere controllo sui blocchi senza entrare sempre in console: elenca i messaggi in quarantena e le azioni disponibili.', '2026-02-20 09:00:00'),
(61, 'email security web - libraesva', 'perché ricevo spam direttamente in casella ma non lo vedo nella console libraesva?', 'Può succedere se lo spam viene inviato direttamente all’IP del tuo mail server bypassando il filtro. Va evitato configurando il server per accettare posta **solo** dai server Utixo.', 'È un bypass “direct delivery”: gli spammer saltano il filtro colpendo l’IP pubblico del server di posta.', 'Se il server accetta consegne dirette, alcuni messaggi non passeranno da Libraesva. Blocca le consegne dirette e consenti solo i relay Utixo.', '2026-02-20 09:00:00'),
(62, 'email security web - libraesva', 'quali ip devo autorizzare per impedire consegne dirette e far passare tutto da libraesva?', 'Per ridurre il rischio di bypass, configura il mail server per accettare email in ingresso solo da: **mx1.utixo.net (46.105.87.130)** e **mx2.utixo.net (5.9.150.87)**.', 'Consenti solo gli IP dei relay Utixo: 46.105.87.130 e 5.9.150.87.', 'Per impedire “direct deliveries”: limita l’SMTP in ingresso ai soli IP dei server Utixo (mx1/mx2).', '2026-02-20 09:00:00');
INSERT INTO `faq` (`id`, `categoria`, `domanda`, `risposta1`, `risposta2`, `risposta3`, `data_aggiornamento`) VALUES
(63, 'email security web - libraesva', 'come creo un utente domain admin per gestire lo spam di tutte le caselle del dominio?', 'Accedi con un utente amministratore, poi vai su **System → Authentication → User Management**, clicca **New**, compila i campi e imposta **User Type = Domain Admin**. Nel campo username indica il dominio su cui avrà diritti amministrativi.', 'Percorso: System → Authentication → User Management → New → User Type “Domain Admin” → salva.', 'Puoi creare un amministratore di dominio dal menu User Management: crea nuovo utente e assegna il tipo “Domain Admin” indicando il dominio interessato.', '2026-02-20 09:00:00'),
(64, 'email security web - libraesva', 'chi può creare un domain admin su libraesva?', 'La creazione del Domain Admin può essere fatta **solo** dall’amministratore del server antispam.', 'Non tutti gli utenti possono farlo: serve un account con permessi da admin del sistema antispam.', 'Il Domain Admin si crea esclusivamente con privilegi amministrativi sul server antispam (operazione riservata).', '2026-02-20 09:00:00'),
(65, 'email security web - libraesva', 'cos è quicksand e perché parla di disarmed file?', 'QuickSand è un sistema di sicurezza che rimuove contenuti attivi da PDF e documenti Office (es. JavaScript nei PDF, macro o script). “Disarmed” significa che l’allegato è stato reso sicuro disabilitando funzioni potenzialmente pericolose.', 'Se vedi “QuickSand disarmed file”, vuol dire che l’allegato è stato neutralizzato (macro/script/JS rimossi o disattivati).', 'QuickSand “disarma” gli allegati per proteggere gli utenti: in rari casi macro legittime possono non funzionare, ma lo scopo è la sicurezza.', '2026-02-20 09:00:00'),
(66, 'email security web - libraesva', 'come mi difendo dal whaling secondo le best practice indicate?', 'Per difenderti dal whaling: imposta **SPF hard fail**, usa **connessioni sicure** (niente password in chiaro), abilita **2FA**, implementa un **controllo accessi** per rilevare accessi anomali e usa **strumenti specifici** di protezione email.', 'Azioni consigliate: SPF hard fail + secure connections + 2FA + access control + strumenti anti-frode.', 'Il whaling colpisce dirigenti/top management: rafforza autenticazione (SPF hard fail/2FA) e monitora accessi sospetti, oltre a usare strumenti di protezione dedicati.', '2026-02-20 09:00:00'),
(67, 'email security web - libraesva', 'in cpanel quali mx devo inserire per usare email security suite libraesva?', 'In cPanel (Zone Editor) elimina gli MX esistenti e inserisci i due record: **mx1.utixo.net** e **mx2.utixo.net**.', 'cPanel → Zone Editor → Manage → filtro MX → cancella vecchi → aggiungi mx1.utixo.net e mx2.utixo.net.', 'La configurazione MX in cPanel prevede la sostituzione degli MX con: mx1.utixo.net e mx2.utixo.net.', '2026-02-20 09:00:00'),
(68, 'google workspace', 'come accedo al pannello di controllo di Google Workspace?', 'Per accedere alla console di amministrazione Google Workspace visita https://admin.google.com ed effettua il login con l’account amministratore del dominio.', 'Apri https://admin.google.com e inserisci le credenziali admin per gestire utenti, sicurezza e servizi.', 'La gestione di Google Workspace avviene dalla Admin Console su https://admin.google.com con account amministratore.', '2026-02-20 09:00:00'),
(69, 'google workspace', 'come verifico il mio piano Google Workspace attivo?', 'Accedi alla Admin Console, vai su **Billing** e seleziona la sottoscrizione per visualizzare tipo di piano, numero licenze e ciclo di fatturazione.', 'Admin Console → Billing → seleziona abbonamento per vedere dettagli del piano.', 'La verifica del piano Workspace si fa nella sezione Billing della console amministrativa.', '2026-02-20 09:00:00'),
(70, 'google workspace', 'come aggiungo una nuova casella email in Google Workspace?', 'Dalla Admin Console vai su **Users** e clicca **Add user** per creare una nuova casella associando una licenza Workspace.', 'Admin Console → Users → Add new user → assegna licenza.', 'Le nuove email si creano nella sezione Users della console admin assegnando una licenza attiva.', '2026-02-20 09:00:00'),
(71, 'google workspace', 'come elimino un utente da Google Workspace?', 'Entra nella Admin Console, vai su **Users**, seleziona l’utente e scegli **Delete user** per rimuoverlo dal dominio.', 'Admin Console → Users → seleziona utente → Delete.', 'Per eliminare un account Workspace accedi alla sezione Users e utilizza l’opzione di cancellazione.', '2026-02-20 09:00:00'),
(72, 'google workspace', 'quali record MX devo inserire per attivare Gmail sul mio dominio?', 'Nel pannello DNS del dominio elimina gli MX esistenti e inserisci quelli forniti da Google Workspace per abilitare Gmail.', 'Zone Editor → elimina MX attuali → aggiungi MX Google per Workspace.', 'Per usare Gmail con il tuo dominio devi configurare correttamente i record MX indicati da Google Workspace nel DNS.', '2026-02-20 09:00:00'),
(73, 'google workspace', 'che record SPF devo configurare per Google Workspace?', 'Il record SPF deve includere Google: esempio `v=spf1 include:_spf.google.com ~all` pubblicato come record TXT nel DNS.', 'SPF consigliato: v=spf1 include:_spf.google.com ~all.', 'Per autorizzare Google a inviare email per il tuo dominio inserisci include:_spf.google.com nel record SPF.', '2026-02-20 09:00:00'),
(74, 'google workspace', 'cos è il transfer token per Google Workspace?', 'Il transfer token è un codice che consente di trasferire la gestione del tuo account Workspace a un nuovo rivenditore senza interrompere il servizio.', 'Serve per autorizzare il cambio di partner Workspace mantenendo attivo l’account.', 'Il token di trasferimento viene generato nella console Google per consentire la migrazione della gestione del servizio.', '2026-02-20 09:00:00'),
(75, 'google workspace', 'come eseguo l upgrade da G Suite a Google Workspace?', 'Accedi alla Admin Console, vai su **Billing** e seleziona il nuovo piano Workspace seguendo la procedura di aggiornamento.', 'Admin Console → Billing → scegli nuovo piano → conferma upgrade.', 'L’upgrade a Workspace si effettua dalla sezione Billing della console amministrativa.', '2026-02-20 09:00:00'),
(76, 'google workspace', 'cos è il piano flexible di Google Workspace?', 'Il Flexible Plan è un abbonamento mensile che consente di aumentare o diminuire le licenze senza vincoli annuali.', 'Con il piano flessibile paghi solo gli utenti attivi nel mese.', 'Il Flexible Plan offre fatturazione mensile variabile in base al numero di licenze utilizzate.', '2026-02-20 09:00:00'),
(77, 'google workspace', 'perché acquistare Google Workspace tramite un partner come Utixo?', 'Un partner autorizzato offre gestione commerciale e supporto diretto mantenendo invariati i servizi ufficiali Google Workspace.', 'Il servizio tecnico resta identico a Google, ma il partner fornisce assistenza e gestione amministrativa.', 'Acquistare tramite partner può semplificare fatturazione e supporto senza modificare le funzionalità Workspace.', '2026-02-20 09:00:00'),
(78, 'cPanel & WHM', 'come configuro un client di posta e accedo alla webmail su hosting cpanel?', 'Dopo aver creato la casella in cPanel, puoi accedere via browser su https://mail.dominio.ext/webmail inserendo email completa e password.', 'Parametri consigliati (SSL): IMAP 993 / POP3 995 / SMTP 465 su mail.dominio.ext, autenticazione obbligatoria.', 'Configurazione base (non SSL, sconsigliata): IMAP 143 / POP3 110 / SMTP 587 su mail.dominio.ext, con autenticazione.', '2026-02-20 09:00:00'),
(79, 'cPanel & WHM', 'come posso esportare la lista di tutti gli indirizzi email in cpanel usando ai?', 'In cPanel puoi visualizzare gli account email e, se ti serve un export, puoi generare un elenco e formattarlo (es. CSV) usando una procedura guidata con ChatGPT come supporto.', 'Obiettivo: ottenere una lista completa degli account email presenti nel dominio e salvarla in un formato esportabile (es. CSV).', 'Se ti serve un output “pulito”, prepara i dati di partenza da cPanel e usa un prompt per trasformarli in elenco/CSV ordinato.', '2026-02-20 09:00:00'),
(80, 'cPanel & WHM', 'come ripristino un backup cpanel da riga di comando via ssh?', 'Puoi eseguire backup/ripristino di un account cPanel via SSH utilizzando gli strumenti di sistema previsti da cPanel (operazione per admin/root).', 'Prima verifica spazio disco e percorso del backup, poi lancia la procedura di restore sull’account interessato.', 'È una procedura avanzata: consigliata solo con accesso root e dopo aver verificato che il backup sia integro.', '2026-02-20 09:00:00'),
(81, 'cPanel & WHM', 'come posso vedere un sito in costruzione non ancora configurato su dns pubblici?', 'Per lavorare su un sito prima della propagazione DNS puoi usare un metodo di “preview” (URL temporaneo o puntamento locale).', 'Soluzione tipica: visualizzare il sito senza DNS pubblici completati, utile per agenzie e ambienti di staging.', 'Verifica che il server risponda correttamente e che il virtual host sia configurato per il dominio/sito.', '2026-02-20 09:00:00'),
(82, 'cPanel & WHM', 'come cerco una stringa dentro i file da terminale su hosting linux?', 'Da terminale puoi usare strumenti come grep per cercare una stringa dentro file e directory (utile per trovare codice, errori o configurazioni).', 'Esempio: ricerca ricorsiva dentro una cartella e stampa i file dove compare la stringa.', 'Per risultati puliti filtra per estensione (es. .php, .log) o usa opzioni per ignorare maiuscole/minuscole.', '2026-02-20 09:00:00'),
(83, 'cPanel & WHM', 'come ripristino file email o tutto l account con jetbackup da cpanel?', 'Accedi a cPanel, apri la sezione JetBackup, scegli cosa ripristinare (file, database, email) oppure “Full Account Backup”.', 'Seleziona il punto di ripristino (data), accetta le condizioni e avvia con Add: l’operazione viene messa in coda.', 'Attenzione: un restore può eliminare e ricreare i dati al punto scelto; tutto ciò creato dopo quel punto può andare perso.', '2026-02-20 09:00:00'),
(84, 'cPanel & WHM', 'come carico e modifico file dal file manager di cpanel?', 'In cPanel apri File Manager, entra nella directory corretta (es. public_html) e usa Upload per caricare file.', 'Puoi selezionare un file e usare Edit/Code Editor per modifiche rapide direttamente dal browser.', 'Per evitare problemi di permessi, verifica ownership e permessi dei file/cartelle dopo upload.', '2026-02-20 09:00:00'),
(85, 'cPanel & WHM', 'come visualizzo i file del sito con il file manager di cpanel?', 'Accedi a cPanel e apri File Manager: naviga nelle cartelle (es. public_html) per vedere struttura e contenuti del sito.', 'Usa View per leggere un file o Download per scaricarlo sul PC.', 'Se non vedi alcuni file, abilita la visualizzazione dei file nascosti (dotfiles) nelle impostazioni del File Manager.', '2026-02-20 09:00:00'),
(86, 'cPanel & WHM', 'come accedo a cpanel dal sito utixo?', 'Accedi all’area clienti Utixo, seleziona il servizio di hosting Linux e usa la voce cPanel dal menu.', 'Clicca su “Control Panel Access” e poi su “Click here” per aprire il pannello.', 'Se hai più servizi, assicurati di selezionare l’hosting corretto prima di aprire cPanel.', '2026-02-20 09:00:00'),
(87, 'cPanel & WHM', 'come permetto agli utenti di disabilitare apache spamassassin in cpanel?', 'Da WHM puoi gestire i permessi/feature per consentire o meno agli utenti di attivare/disattivare SpamAssassin.', 'La gestione passa tipicamente da feature list o impostazioni del servizio email nel pannello WHM.', 'Applica la modifica al pacchetto/feature list usato dagli account interessati e verifica in cPanel.', '2026-02-20 09:00:00'),
(88, 'cPanel & WHM', 'come navigo un sito tramite file hosts prima della propagazione del dominio?', 'Puoi modificare il file hosts del tuo PC per forzare il dominio a puntare a un IP specifico prima che il DNS si propaghi.', 'Così il browser risolve il dominio verso l’IP scelto solo sul tuo computer (utile per test e staging).', 'Ricordati di rimuovere la riga dal file hosts quando hai finito i test, per tornare alla risoluzione DNS normale.', '2026-02-20 09:00:00'),
(89, 'cPanel & WHM', 'come cambio la password di una casella email da cpanel?', 'In cPanel vai su Email Accounts, trova la casella e usa Manage/Password per impostare una nuova password.', 'Scegli una password robusta e salva; poi aggiorna i client di posta (Outlook/telefono) con la nuova password.', 'Se usi webmail, dopo il cambio fai logout/login per verificare che la nuova password funzioni.', '2026-02-20 09:00:00'),
(90, 'cPanel & WHM', 'come cambio default_charset in php.ini da cpanel?', 'Da cPanel puoi gestire alcune impostazioni PHP (a seconda del piano) e aggiornare parametri come default_charset.', 'Dopo la modifica, salva e verifica con un phpinfo o controllando il comportamento del sito.', 'Se l’opzione non è disponibile in cPanel, potrebbe essere necessaria una modifica lato server (WHM/root).', '2026-02-20 09:00:00'),
(91, 'cPanel & WHM', 'backup su hosting condiviso come si collega a gdpr e buone pratiche?', 'Le procedure di backup devono rispettare principi di sicurezza e minimizzazione: proteggi accessi, cifratura e conservazione.', 'Assicurati che i dati personali inclusi nei backup siano trattati in modo conforme (accessi limitati, retention coerente).', 'Mantieni procedure di restore testate e documentate per ridurre downtime e rischi di perdita dati.', '2026-02-20 09:00:00'),
(92, 'cPanel & WHM', 'ho cancellato file ma la quota disco in cpanel non cambia come aggiorno?', 'La quota mostrata da cPanel può non aggiornarsi in tempo reale; puoi forzare un ricalcolo/aggiornamento della quota.', 'Dopo pulizia di file/cestino, esegui l’azione di aggiornamento quota o attendi il refresh del sistema.', 'Se la quota resta errata, controlla file nascosti o cartelle .trash che continuano a occupare spazio.', '2026-02-20 09:00:00'),
(93, 'cPanel & WHM', 'errore dominio ha superato max defers and failures per hour cosa significa?', 'Significa che il dominio ha superato il numero massimo di messaggi differiti (defers) e falliti in un’ora.', 'Riduci errori di consegna: verifica code SMTP, credenziali, reputazione, errori di routing e indirizzi destinatari.', 'Se necessario, attendi il reset della finestra oraria e risolvi la causa per evitare che si ripresenti.', '2026-02-20 09:00:00'),
(94, 'cPanel & WHM', 'quali sono i limiti del servizio email su hosting condiviso?', 'Su shared hosting esistono limiti per prevenire abusi (es. invii orari/giornalieri, connessioni, rate).', 'Se superi i limiti potresti vedere blocchi temporanei o errori in invio/ricezione.', 'Per esigenze più alte valuta un relay SMTP dedicato o un servizio email professionale.', '2026-02-20 09:00:00'),
(95, 'cPanel & WHM', 'che differenza c è tra antispam standard cpanel e protezione avanzata libraesva?', 'Su piani standard l’antispam base è spesso Apache SpamAssassin; per protezione più avanzata è disponibile Libraesva (SaaS).', 'SpamAssassin assegna punteggi e filtra; Libraesva aggiunge funzioni evolute per phishing, malware e controllo link/allegati.', 'Se ricevi molto spam o phishing, la soluzione avanzata è consigliata rispetto al filtro base.', '2026-02-20 09:00:00'),
(96, 'cPanel & WHM', 'errore max_user_connections su mysql cosa vuol dire?', 'L’errore indica che l’utente MySQL ha superato il massimo numero di connessioni contemporanee consentite.', 'Risolvi ottimizzando l’applicazione (chiusura connessioni, pooling), riducendo query lente e controllando picchi di traffico.', 'Se serve, valuta aumento del limite lato server (WHM) o revisione della configurazione DB.', '2026-02-20 09:00:00'),
(97, 'cPanel & WHM', 'come esporto un database mysql da cpanel?', 'Puoi esportare un database da cPanel tramite phpMyAdmin o strumenti di backup/export previsti dal pannello.', 'In phpMyAdmin selezioni il DB e usi Export per scaricare un file .sql.', 'Per DB grandi, usa metodi compressi o export via SSH per evitare timeout.', '2026-02-20 09:00:00'),
(98, 'cPanel & WHM', 'quali file nascosti occupano spazio e come elimino .trash su cpanel?', 'Alcune cartelle nascoste (es. .trash) possono occupare molto spazio anche dopo aver cancellato file.', 'Controlla nel File Manager (mostra file nascosti) ed elimina contenuti non necessari, poi svuota eventuali cestini.', 'Dopo la pulizia, aggiorna quota disco o attendi l’aggiornamento per vedere lo spazio liberato.', '2026-02-20 09:00:00'),
(99, 'cPanel & WHM', 'come libero spazio disco con accesso root al server?', 'Con accesso root puoi individuare le directory che consumano più spazio e intervenire su log, cache, backup e file temporanei.', 'Esegui analisi uso disco (du/df) e pulisci in modo sicuro evitando percorsi critici di sistema.', 'Prima di cancellare, verifica cosa è generato automaticamente (logrotate, cache applicative) e imposta retention corretta.', '2026-02-20 09:00:00'),
(100, 'cPanel & WHM', 'come controllo l utilizzo disco del mio account cpanel?', 'In cPanel usa gli strumenti di “Disk Usage” per vedere quanto spazio occupano cartelle e file principali.', 'Individua le directory più pesanti (backup, log, media, cache) e valuta pulizia o ottimizzazione.', 'Se sei vicino al limite quota, riduci file inutili e usa backup esterni invece di conservarli sullo stesso hosting.', '2026-02-20 09:00:00'),
(101, 'cPanel & WHM', 'come configuro web disk webdav in cpanel per gestire file da pc o smartphone?', 'In cPanel vai su Web Disk (Files), crea un account indicando username, dominio, password, directory e permessi (RO/RW).', 'Per Windows abilita digest authentication e usa “Configure Client Access” per scaricare lo script di configurazione.', 'Su mobile usa app WebDAV (es. iOS Documents / Android WebDAV Navigator) con credenziali Web Disk.', '2026-02-20 09:00:00'),
(102, 'cPanel & WHM', 'come creo un indirizzo email da cpanel?', 'In cPanel crea una nuova casella scegliendo nome (es. info), dominio, quota (Unlimited o custom) e password forte.', 'Se hai più domini nello stesso hosting, seleziona dal menu a tendina quello corretto.', 'Dopo creazione, configura webmail o client (IMAP consigliato se usi più dispositivi).', '2026-02-20 09:00:00'),
(103, 'cPanel & WHM', 'come creo e gestisco un filtro email in cpanel?', 'In cPanel puoi creare filtri email per applicare regole su messaggi in ingresso (es. sposta, elimina, inoltra).', 'Definisci condizioni (mittente, oggetto, parole) e azioni, poi salva la regola.', 'Testa la regola con una mail di prova per assicurarti che non blocchi messaggi legittimi.', '2026-02-20 09:00:00'),
(104, 'cPanel & WHM', 'come disabilito le email di notifica autossl in cpanel?', 'Se ricevi troppe notifiche AutoSSL, puoi disattivare le email di notifica dalle impostazioni relative ad AutoSSL.', 'La modifica riguarda la notifica, non l’emissione del certificato: verifica comunque stato SSL del dominio.', 'Dopo la disattivazione, controlla che le scadenze siano monitorate tramite pannello o alert alternativi.', '2026-02-20 09:00:00'),
(105, 'cPanel & WHM', 'come disabilito il directory indexing di apache via whm?', 'Da WHM puoi disabilitare il directory listing per aumentare la sicurezza ed evitare l’elenco file nelle cartelle senza index.', 'Applica l’impostazione a livello di server o template di configurazione web, poi verifica su una directory test.', 'Dopo il cambio, controlla che non ci siano cartelle che dipendono dal listing (di solito è sconsigliato lasciarlo attivo).', '2026-02-20 09:00:00'),
(106, 'cPanel & WHM', 'come libero spazio disco da cpanel senza accesso root?', 'Da cPanel puoi liberare spazio eliminando backup vecchi, file inutili, log scaricati, cache e directory pesanti.', 'Usa Disk Usage per capire cosa occupa di più e File Manager per cancellare in sicurezza.', 'Se usi JetBackup, evita di conservare copie locali troppo grandi: scaricale e rimuovile dal server.', '2026-02-20 09:00:00'),
(107, 'cPanel & WHM', 'come proteggo una cartella con password usando .htaccess in cpanel?', 'In cPanel puoi password-proteggere una directory creando autenticazione (htpasswd) e regole .htaccess.', 'Imposta utente/password e applica la protezione alla cartella desiderata; poi verifica accesso da browser.', 'Se il sito usa cache o CMS, controlla che non blocchi risorse pubbliche necessarie (css/js).', '2026-02-20 09:00:00'),
(108, 'cPanel & WHM', 'come riduco lo spam e miglioro la deliverability delle email?', 'Riduci spam e migliora consegna configurando correttamente DNS (SPF/DKIM/DMARC), usando password forti e limitando invii anomali.', 'Evita invii massivi da shared hosting, controlla blacklist e monitora errori/defers in uscita.', 'Se serve, usa un servizio antispam/antiphishing avanzato e/o un relay SMTP professionale.', '2026-02-20 09:00:00'),
(109, 'cPanel & WHM', 'come resetto la scelta dell applicazione webmail predefinita in cpanel?', 'Se hai impostato un webmail predefinito (Roundcube/Horde ecc.) e vuoi reimpostarlo, usa l’opzione di reset della selezione webmail.', 'Dopo il reset, al prossimo accesso webmail ti verrà richiesto di scegliere di nuovo l’applicazione.', 'Utile quando l’app selezionata non funziona come previsto o vuoi cambiare client webmail.', '2026-02-20 09:00:00'),
(110, 'cPanel & WHM', 'come cerco dati dentro un database con phpmyadmin?', 'In phpMyAdmin puoi usare la funzione Search per cercare testo/valori dentro tabelle e campi del database.', 'Seleziona il database, apri Search, inserisci il valore e scegli le tabelle/campi da includere.', 'Per risultati migliori, limita la ricerca alle tabelle rilevanti e verifica encoding/collation se ci sono caratteri speciali.', '2026-02-20 09:00:00'),
(111, 'cPanel & WHM', 'come cambio il logo webmail in whm cp nel webmail di cpanel?', 'Serve accesso root: collegati via SSH/WinSCP e vai in /usr/local/cpanel/base/unprotected/cpanel/images/.', 'Sostituisci il file webmail-logo.svg con il tuo logo personalizzato (formato SVG).', 'Dopo la sostituzione, il nuovo logo comparirà nell’interfaccia Webmail di cPanel.', '2026-02-20 09:00:00'),
(112, 'cPanel & WHM', 'come creo un inoltro email forwarder con cpanel?', 'In cPanel vai su Forwarders, crea un nuovo inoltro scegliendo l’indirizzo sorgente e la destinazione.', 'Puoi inoltrare verso un’altra casella interna o un indirizzo esterno.', 'Dopo la creazione, testa con una mail di prova e verifica eventuali loop di inoltro.', '2026-02-20 09:00:00'),
(113, 'cPanel & WHM', 'come creo e scarico un backup completo sito ed email da cpanel?', 'In cPanel apri JetBackup, vai su Full Backups, seleziona il backup da esportare e clicca Generate Download.', 'Quando la generazione è completata compare Download: scarichi sito completo e dati email in locale.', 'È consigliato conservare il backup anche fuori dal server (PC o storage esterno) per sicurezza.', '2026-02-20 09:00:00'),
(114, 'cPanel & WHM', 'come abilito la protezione antispam base in cpanel con spamassassin?', 'Accedi a cPanel (da area clienti Utixo), vai in Email e apri Apache SpamAssassin.', 'Attiva “Process New Emails and Mark them as Spam” per abilitare il filtro.', 'Puoi impostare Auto-delete sopra una soglia di punteggio (es. 6) per eliminare automaticamente lo spam alto.', '2026-02-20 09:00:00'),
(115, 'cPanel & WHM', 'come gestisco i cron jobs in cpanel?', 'In cPanel apri Cron Jobs e imposta la pianificazione (minuto/ora/giorno/mese) e il comando da eseguire.', 'Usa comandi con percorsi assoluti e redireziona output (log) per debugging.', 'Prima prova il comando manualmente e poi programma l’esecuzione con frequenza adeguata.', '2026-02-20 09:00:00'),
(116, 'cPanel & WHM', 'come gestisco i file del server con filezilla?', 'Installa FileZilla, crea una connessione (FTP/SFTP) con host, username e password del tuo hosting.', 'Carica/scarica file trascinandoli; mantieni la struttura corretta (es. public_html).', 'Preferisci SFTP quando disponibile e conserva le credenziali in modo sicuro.', '2026-02-20 09:00:00'),
(117, 'cPanel & WHM', 'come modifico il livello di php error reporting?', 'Puoi regolare l’error reporting PHP per mostrare/nascondere avvisi e errori (utile in sviluppo, da limitare in produzione).', 'Dopo la modifica, verifica che non vengano esposti dettagli sensibili agli utenti finali.', 'In produzione è consigliato loggare gli errori invece di mostrarli a schermo.', '2026-02-20 09:00:00'),
(118, 'cPanel & WHM', 'dove si trovano i file fisici dei database mysql sul server?', 'I file di MySQL (datadir) risiedono in una directory specifica del server configurata da MySQL.', 'È un’informazione utile per admin/root per backup, diagnostica e gestione storage.', 'Su shared hosting normalmente non è necessario accedere direttamente ai file: usa cPanel/phpMyAdmin/backup.', '2026-02-20 09:00:00'),
(119, 'cPanel & WHM', 'come accedo a phpmyadmin da cpanel?', 'phpMyAdmin è disponibile in cPanel: apri la sezione Database e clicca phpMyAdmin per entrare.', 'Da lì puoi gestire database, tabelle, query, import/export.', 'Se hai più database, seleziona quello corretto dalla colonna sinistra prima di operare.', '2026-02-20 09:00:00'),
(120, 'cPanel & WHM', 'la dimensione di una casella email in cpanel è sbagliata come la ricalcolo?', 'A volte cPanel mostra dimensioni errate della casella: puoi forzare il ricalcolo della size dell’account email.', 'Dopo il ricalcolo, la quota usata dovrebbe aggiornarsi correttamente.', 'Se resta sballata, verifica cartelle grandi (Sent/Trash/Junk) e pulisci contenuti inutili.', '2026-02-20 09:00:00'),
(121, 'cPanel & WHM', 'come abilito l accesso remoto a un database mysql?', 'Per accesso remoto devi autorizzare host/IP esterni (Remote MySQL) e usare un utente con permessi adeguati.', 'Aggiungi l’IP autorizzato e verifica che firewall/porta MySQL permettano la connessione.', 'Per sicurezza limita agli IP necessari e usa password robuste; se possibile usa tunnel SSH.', '2026-02-20 09:00:00'),
(122, 'cPanel & WHM', 'backup hosting cpanel quanto dura la retention e cosa significa?', 'La retention indica per quanto tempo vengono conservati i backup (numero di giorni/restore point disponibili).', 'Più retention = più punti di ripristino, ma anche maggiore uso di storage e policy di conservazione.', 'Per esigenze particolari valuta backup esterno o soluzioni dedicate oltre al backup standard.', '2026-02-20 09:00:00'),
(123, 'cPanel & WHM', 'come scarico e visualizzo i log del sito in cpanel?', 'In cPanel puoi scaricare e consultare access log e error log del sito per diagnosticare problemi.', 'Scarica i raw access logs o visualizza gli errori direttamente dagli strumenti di log.', 'Usa i log per individuare 404, errori 500, bot aggressivi e problemi di permessi/configurazione.', '2026-02-20 09:00:00'),
(124, 'cPanel & WHM', 'come passo un sito da http a https e risolvo mixed content?', 'Per migrare a HTTPS abilita SSL, forza redirect da HTTP a HTTPS e correggi risorse in chiaro (mixed content).', 'Aggiorna URL assoluti (immagini/css/js) e verifica configurazione CMS (WordPress: siteurl/home).', 'Dopo la migrazione, testa pagine chiave e controlla console del browser per eventuali risorse ancora in HTTP.', '2026-02-20 09:00:00'),
(125, 'cPanel & WHM', 'cos è whm e a cosa serve rispetto a cpanel?', 'WHM (Web Host Manager) è il pannello per amministrare più account cPanel da un’unica dashboard, tipico di reseller/admin.', 'Con WHM gestisci creazione account, risorse, pacchetti, sicurezza e configurazioni server.', 'cPanel è il pannello del singolo account; WHM è per la gestione “server/hosting multi-account”.', '2026-02-20 09:00:00'),
(126, 'cPanel & WHM', 'come cambio l ip di uscita usato per inviare email su cpanel whm?', 'Accedi a WHM → Exim Configuration Manager e abilita “Reference /etc/mailips for outgoing SMTP connections”.', 'Via SSH modifica /etc/mailips e aggiungi una riga tipo: *: 203.0.113.33 sostituendo l’IP desiderato.', 'Se sei in NAT, inserisci l’IP privato invece dell’IP pubblico.', '2026-02-20 09:00:00');

